const body = $input.first().json.body || {};
const vatRate = body.vatRate ?? 0.21;
const rates = { callOutLocal: 25, callOutExtended: 40, hourStandard: 30, hourUrgent: 45, minimumJob: 45, kmRate: 0.35, ...(body.rates || {}) };
const hours = Number(body.hours || 1);
const distanceKm = Number(body.distanceKm || 0);
const urgent = Boolean(body.urgent);
const labor = Math.max(hours * (urgent ? rates.hourUrgent : rates.hourStandard), rates.minimumJob);
const callOut = distanceKm > 15 ? rates.callOutExtended : rates.callOutLocal;
const kmCost = Math.max(distanceKm - 10, 0) * rates.kmRate;
const materials = Array.isArray(body.materials) ? body.materials : [];
const materialsSale = materials.reduce((sum, item) => sum + Number(item.salePrice || 0) * Number(item.qty || 0), 0);
const subtotal = labor + callOut + kmCost + materialsSale;
const vat = subtotal * vatRate;
const total = subtotal + vat;
const rows = [['Salida / diagnostico', 1, callOut], ['Mano de obra', hours, labor], ...(kmCost > 0 ? [['Kilometraje adicional', distanceKm, kmCost]] : []), ...materials.map(item => [item.name || item.id || 'Material', item.qty || 1, Number(item.salePrice || 0) * Number(item.qty || 0)])];
const htmlRows = rows.map(row => '<tr><td>' + row[0] + '</td><td>' + row[1] + '</td><td style="text-align:right">' + row[2].toFixed(2) + ' EUR</td></tr>').join('');
const html = '<!doctype html><html><head><meta charset="utf-8"><title>Presupuesto Astoreka MTO</title><style>body{font-family:Arial;margin:32px;color:#1f2933}header{border-bottom:3px solid #075b63;margin-bottom:20px}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #d8e0e7;padding:8px}th{text-align:left}.total{font-size:20px}</style></head><body><header><h1>Astoreka MTO</h1><p>Presupuesto</p></header><p><strong>Cliente:</strong> ' + (body.clientName || 'Cliente pendiente') + '</p><p><strong>Trabajo:</strong> ' + (body.description || '') + '</p><table><thead><tr><th>Concepto</th><th>Cantidad</th><th>Importe</th></tr></thead><tbody>' + htmlRows + '</tbody></table><p>Subtotal: ' + subtotal.toFixed(2) + ' EUR</p><p>IVA: ' + vat.toFixed(2) + ' EUR</p><p class="total"><strong>Total: ' + total.toFixed(2) + ' EUR</strong></p></body></html>';
return [{ json: { type: 'presupuesto', clientName: body.clientName, subtotal, vat, total, html, status: 'generated' } }];
